INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Programm immer den Zustand ändert?', 2, '[{"text": "Ja", "correct": true, "because": "Zustandsänderung ist typisch"}, {"text": "Nein", "correct": false, "because": "Kernmerkmal"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend, um eine Abfolge von Schritten zu definieren?', 3, '[{"text": "Anweisungen", "correct": true, "because": "Steuern Ablauf"}, {"text": "Funktionen", "correct": false, "because": "Nur Teil davon"}, {"text": "Klassen", "correct": false, "because": "Objektorientiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat ein schrittweises Programm?', 5, '[{"text": "Variablenänderung", "correct": true, "because": "Zustand wird manipuliert"}, {"text": "Sequenzielle Ausführung", "correct": true, "because": "Schritt für Schritt"}, {"text": "Keine Zustände", "correct": false, "because": "Gegenteil"}, {"text": "Abstrakte Klassen", "correct": false, "because": "Anderes Paradigma"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Es nutzt Schleifen für Wiederholung. b) Es vermeidet Zustandsänderungen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich einen Ablauf in C programmiere?', 4, '[{"text": "Reihenfolge", "correct": false, "because": "Entscheidend für Logik"}, {"text": "Variablen", "correct": false, "because": "Speichern Zustände"}, {"text": "Codefarbe", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Programm ohne Zustandsänderung möglich ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Zustandsänderung ist Kern"}, {"text": "Ja", "correct": false, "because": "Anderes Paradigma"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Struktur wähle ich, um eine Bedingung zu prüfen?', 3, '[{"text": "if-Anweisung", "correct": true, "because": "Steuert Ablauf"}, {"text": "Funktion", "correct": false, "because": "Nur Aufruf"}, {"text": "Klasse", "correct": false, "because": "Objektorientiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften hat ein typisches Programm?', 5, '[{"text": "Schrittweise Anweisungen", "correct": true, "because": "Definiert Ablauf"}, {"text": "Zustandsmanipulation", "correct": true, "because": "Ändert Variablen"}, {"text": "Keine Variablen", "correct": false, "because": "Gegenteil"}, {"text": "Abstrakte Logik", "correct": false, "because": "Funktional"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass a) Schleifen typisch sind und b) es keine Funktionen nutzt. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Funktionen sind möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um eine Abfolge in Python zu schreiben?', 4, '[{"text": "Variablen", "correct": false, "because": "Speichern Zustände"}, {"text": "Anweisungen", "correct": false, "because": "Steuern Ablauf"}, {"text": "Klassen", "correct": true, "because": "Objektorientiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist eine Funktion ohne Zustandsänderung möglich?', 2, '[{"text": "Nein", "correct": true, "because": "Änderung ist typisch"}, {"text": "Ja", "correct": false, "because": "Funktional anders"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Techniken nutze ich für Wiederholungen?', 4, '[{"text": "for-Schleife", "correct": true, "because": "Iteriert über Liste"}, {"text": "while-Schleife", "correct": true, "because": "Bedingte Wiederholung"}, {"text": "Rekursion", "correct": false, "because": "Funktional oft"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass es keine Variablen braucht. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Variablen sind zentral"}, {"text": "Ja", "correct": false, "because": "Zustandsänderung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einer Abfolge von Anweisungen?', 3, '[{"text": "Zustand steuern", "correct": true, "because": "Ändert Programmverlauf"}, {"text": "Abstrakte Logik", "correct": false, "because": "Funktional"}, {"text": "Keine Änderungen", "correct": false, "because": "Gegenteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Es nutzt Variablen. b) Es ist deklarativ.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Deklarativ ist anders"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt eine Variable in einem Programm?', 4, '[{"text": "Zustand speichern", "correct": true, "because": "Änderungen verfolgen"}, {"text": "Logik abstrahieren", "correct": false, "because": "Funktional"}, {"text": "Design verbessern", "correct": false, "because": "Kein Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Programm ohne Schleifen auskommt?', 2, '[{"text": "Ja", "correct": true, "because": "Nicht zwingend"}, {"text": "Nein", "correct": false, "because": "Optional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen ein Programm schrittweise?', 5, '[{"text": "Anweisungsfolge", "correct": true, "because": "Definiert Ablauf"}, {"text": "Zustandsänderung", "correct": true, "because": "Manipuliert Daten"}, {"text": "Keine Zustände", "correct": false, "because": "Gegenteil"}, {"text": "Abstrakte Klassen", "correct": false, "because": "Objektorientiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Python immer so programmiert?', 3, '[{"text": "Nein", "correct": true, "because": "Auch funktional möglich"}, {"text": "Ja", "correct": false, "because": "Flexibel einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu einem schrittweisen Ansatz?', 4, '[{"text": "Zähler erhöhen", "correct": true, "because": "Zustandsänderung"}, {"text": "Mathematische Formel", "correct": false, "because": "Funktional"}, {"text": "Datenbankabfrage", "correct": false, "because": "Deklarativ"}]');
